import java.util.ArrayList;
import java.util.List;

public class PecsAndErasureDemo {
    // PECS in action: Producer Extends, Consumer Super
    public static <T> void copyElements(List<? extends T> src, List<? super T> dest) {
        for (T item : src) {
            dest.add(item);
        }
    }

    public static void main(String[] args) {
        // 1. PECS Demonstration: Copy Integer producer into Number consumer
        List<Integer> intProducer = List.of(10, 20, 30);
        List<Number> numConsumer = new ArrayList<>();
        copyElements(intProducer, numConsumer);
        System.out.println("Copied via PECS: " + numConsumer); // [10, 20, 30]

        // 2. Type Erasure Runtime Proof
        List<String> strList = new ArrayList<>();
        List<Integer> intList = new ArrayList<>();

        // At runtime, both share the EXACT SAME Class object!
        boolean sameClass = strList.getClass() == intList.getClass();
        System.out.println("Runtime Class identity identical? " + sameClass); // true
        System.out.println("Runtime Class name: " + strList.getClass().getName()); // java.util.ArrayList
    }
}
// Expected Output:
// Copied via PECS: [10, 20, 30]
// Runtime Class identity identical? true
// Runtime Class name: java.util.ArrayList

