import java.util.ArrayList;
import java.util.List;

public class DataPipeline {
    public interface Mapper<F, T> {
        T map(F input);
    }

    // src produces F (extends F); dst consumes T (super T)
    public static <F, T> void transform(
        List<? extends F> src,
        List<? super T> dst,
        Mapper<F, T> mapper
    ) {
        for (F item : src) {
            dst.add(mapper.map(item));
        }
    }

    public static void main(String[] args) {
        List<Integer> sourceValues = List.of(1, 2, 3, 4);
        List<Object> targetStrings = new ArrayList<>();

        // Mapper converts Integer to formatted String
        transform(sourceValues, targetStrings, n -> "Item_#" + (n * 10));

        System.out.println("Pipeline Output: " + targetStrings);
    }
}

