import java.util.Map;
import java.util.HashMap;
import java.util.Objects;

public class TypedTokenRegistry {
    private final Map<Class<?>, Object> registry = new HashMap<>();

    public <T> void bind(Class<T> type, T instance) {
        Objects.requireNonNull(type, "Type token cannot be null");
        registry.put(type, instance);
    }

    public <T> T resolve(Class<T> type) {
        Objects.requireNonNull(type, "Type token cannot be null");
        Object obj = registry.get(type);
        return type.cast(obj);
    }

    public static void main(String[] args) {
        TypedTokenRegistry reg = new TypedTokenRegistry();
        reg.bind(String.class, "ProductionService");
        reg.bind(Integer.class, 8080);
        System.out.println(reg.resolve(String.class));
        System.out.println(reg.resolve(Integer.class));
    }
}

