import java.util.List;
import java.util.Comparator;

public class PecsMaxFinder {
    public static <T> T findMax(List<? extends T> items, Comparator<? super T> comparator) {
        if (items == null || items.isEmpty() || comparator == null) return null;
        T max = items.get(0);
        for (int i = 1; i < items.size(); i++) {
            T curr = items.get(i);
            if (comparator.compare(curr, max) > 0) {
                max = curr;
            }
        }
        return max;
    }

    public static void main(String[] args) {
        List<Integer> ints = List.of(10, 45, 23, 89, 12);
        Comparator<Number> numComp = (a, b) -> Double.compare(a.doubleValue(), b.doubleValue());
        System.out.println(findMax(ints, numComp));
    }
}

